// Keeps the latest SmartFlex session data for the daily summary, and sends a short
// message as soon as a new charging session has finished.
// Octopus session data is read every 30 minutes, so the message can arrive up to
// about half an hour after the car stops.

const TIME_ZONE = 'Europe/London'; // EDIT: used for the times in the text
const when = (iso) => (iso ? new Date(iso).toLocaleString('en-GB', { timeZone: TIME_ZONE, weekday: 'short', hour: '2-digit', minute: '2-digit' }) : '?');
const describe = (s) => {
    const kwh = typeof s.kwh_added === 'number' ? `${s.kwh_added.toFixed(1)} kWh` : 'unknown kWh';
    const soc = typeof s.soc_final === 'number' ? `, ended at ${s.soc_final}%` : '';
    const cost = s.cost && typeof s.cost.amount === 'number'
        ? (s.cost.currency === 'GBP' ? `, cost £${s.cost.amount.toFixed(2)}` : `, cost ${s.cost.amount} ${s.cost.currency || ''}`.trim())
        : '';
    const problems = s.problems && s.problems.length ? `. Problems: ${s.problems.join(', ')}` : '';
    return `${when(s.start)} to ${when(s.end)}: ${kwh}${soc}${cost}${problems}`;
};

const p = msg.payload;
if (!p || typeof p !== 'object') return null;

// Only store once the vehicle has been read (charging_sessions starts as an empty list).
if (p.last_session || (Array.isArray(p.charging_sessions) && p.charging_sessions.length)) {
    flow.set('vehicleSessions', {
        vehicle: [p.vehicle_make, p.vehicle_model].filter(Boolean).join(' ') || 'Your car',
        last_session: p.last_session,
        charging_sessions: p.charging_sessions || [],
        read_at: new Date().toISOString(),
    });
}
flow.set('vehicleError', p.smartflex_vehicle_error || null);

const last = p.last_session;
if (!last) return null;
const key = `${last.start}|${last.end}`;
const known = context.get('lastSessionKey');
context.set('lastSessionKey', key);
// The first session seen after a deploy is the baseline, not news.
if (!known || known === key) return null;
return { topic: 'Charging session finished', payload: `Charging session finished. ${describe(last)}.` };

// Builds a short daily summary from the sessions the node has read (last 5 sessions).
//
// ===== EDIT THESE =====
const SUMMARY_HOURS = 24; // sessions that ended within this many hours count as "today"
// TIME_ZONE is the EDIT line just below this block.
// ======================

const TIME_ZONE = 'Europe/London'; // EDIT: used for the times in the text
const when = (iso) => (iso ? new Date(iso).toLocaleString('en-GB', { timeZone: TIME_ZONE, weekday: 'short', hour: '2-digit', minute: '2-digit' }) : '?');
const describe = (s) => {
    const kwh = typeof s.kwh_added === 'number' ? `${s.kwh_added.toFixed(1)} kWh` : 'unknown kWh';
    const soc = typeof s.soc_final === 'number' ? `, ended at ${s.soc_final}%` : '';
    const cost = s.cost && typeof s.cost.amount === 'number'
        ? (s.cost.currency === 'GBP' ? `, cost £${s.cost.amount.toFixed(2)}` : `, cost ${s.cost.amount} ${s.cost.currency || ''}`.trim())
        : '';
    const problems = s.problems && s.problems.length ? `. Problems: ${s.problems.join(', ')}` : '';
    return `${when(s.start)} to ${when(s.end)}: ${kwh}${soc}${cost}${problems}`;
};

const data = flow.get('vehicleSessions');
const err = flow.get('vehicleError');
if (!data) {
    const why = err ? ` Last error: ${err}` : '';
    return { topic: 'Daily charging summary', payload: `No SmartFlex session data yet. The node reads it every 30 minutes.${why}` };
}

const cutoff = Date.now() - SUMMARY_HOURS * 3600000;
const recent = data.charging_sessions.filter((s) => s.end && Date.parse(s.end) >= cutoff);
const kwh = recent.reduce((sum, s) => sum + (typeof s.kwh_added === 'number' ? s.kwh_added : 0), 0);
const pounds = recent.reduce((sum, s) => sum + (s.cost && s.cost.currency === 'GBP' && typeof s.cost.amount === 'number' ? s.cost.amount : 0), 0);

const lines = [];
if (recent.length) {
    lines.push(`${data.vehicle}: ${recent.length} session${recent.length === 1 ? '' : 's'} in the last ${SUMMARY_HOURS} hours, ${kwh.toFixed(1)} kWh, £${pounds.toFixed(2)}.`);
    recent.forEach((s) => lines.push(`- ${describe(s)}`));
} else {
    lines.push(`${data.vehicle}: no charging sessions ended in the last ${SUMMARY_HOURS} hours.`);
    if (data.last_session) lines.push(`Last session: ${describe(data.last_session)}.`);
}
if (err) lines.push(`Note: the last vehicle read had an error: ${err}`);

return { topic: 'Daily charging summary', payload: lines.join('\n') };
